'use strict';
// node count.js <store-file> <bo1|bo3> <ladder.json> <out.json>
const fs = require('fs'), zlib = require('zlib'), readline = require('readline');
const WT = 'C:/Users/willj/Projects/Pokemon/ABRA/.claude/worktrees/agent-a2fe7875c9565f705';
const Q = require(WT + '/engine/quality.js');
const [file, kind, ladderFile, outFile] = process.argv.slice(2);
const cfg = Q.config();
const uid = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const normMv = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');

(async () => {
  const st = fs.statSync(file);
  let stream = fs.createReadStream(file);
  if (file.endsWith('.gz')) stream = stream.pipe(zlib.createGunzip());
  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
  const seen = new Set(); let lines = 0, dup = 0, bad = 0;
  const G = [];
  let minDate = null, maxDate = null;
  for await (const line of rl) {
    const s = line.trim(); if (!s) continue; lines++;
    let g; try { g = JSON.parse(s); } catch (e) { bad++; continue; }
    if (seen.has(g.id)) { dup++; continue; }
    seen.add(g.id);
    if (!minDate || g.date < minDate) minDate = g.date;
    if (!maxDate || g.date > maxDate) maxDate = g.date;
    const rs = Q.reasons(g, cfg, null);           // canonical, minus the behavioural-bot rule
    const turns = g.turns || [];
    const br = g.brought || {};
    const opsClean = !(g.p1 && g.p1.bot) && !(g.p2 && g.p2.bot)
      && (br.p1 || []).length === 4 && (br.p2 || []).length === 4;
    const rec = {
      id: g.id, date: g.date, num: +String(g.id).split('-').pop(),
      p1: { name: (g.p1 || {}).name, rating: (g.p1 || {}).rating }, p2: { name: (g.p2 || {}).name, rating: (g.p2 || {}).rating },
      six: g.six, winner: g.winner, rs,
      opsLen: opsClean && turns.length >= 3,
      opsN3: opsClean && turns.some(t => t.n === 3),
    };
    // reveal (bo1): per sets entry
    if (kind === 'bo1') {
      const e = [];
      for (const [k, v] of Object.entries(g.sets || {})) {
        const mv = new Set((v.moves || []).map(normMv));
        e.push({ mega: /mega/.test(k), mv: Math.min(4, mv.size), item: !!v.item, ab: !!v.ability });
      }
      rec.sets = e;
    } else {
      const sc = {};
      for (const sd of ['p1', 'p2']) sc[sd] = ((g.sheets || {})[sd] || []).some(m => /choicescarf/i.test(String(m.item || '').replace(/\s/g, '')));
      rec.scarf = sc;
    }
    G.push(rec);
  }
  const bots = Q.behaviouralBots(G, cfg);
  for (const r of G) {
    if ((r.p1 && bots.has(r.p1.name)) || (r.p2 && bots.has(r.p2.name))) r.rs = r.rs.concat('behavioural_bot');
    r.clean = r.rs.length === 0;
    r.cleanNoBehav = r.rs.filter(x => x !== 'behavioural_bot').length === 0;
  }
  const lo = r => Math.min(+r.p1.rating || 0, +r.p2.rating || 0);
  const hi = r => Math.max(+r.p1.rating || 0, +r.p2.rating || 0);
  const TH = [1300, 1400, 1500, 1600];
  function band(sel) {
    const S = G.filter(sel);
    const o = { games: S.length, lower: {}, higher: {} };
    for (const t of TH) { o.lower[t] = S.filter(r => lo(r) >= t).length; o.higher[t] = S.filter(r => hi(r) >= t).length; }
    return o;
  }
  const reasonsTally = {};
  for (const r of G) for (const x of r.rs) reasonsTally[x] = (reasonsTally[x] || 0) + 1;
  const out = {
    file, kind, bytes: st.size, mtime: st.mtime.toISOString(), lines, dup, parse_errors: bad,
    unique_games: G.length, date_min: minDate, date_max: maxDate,
    behavioural_bots: [...bots], reasons_tally: reasonsTally,
    defs: {
      ops_turnslen3: band(r => r.opsLen),
      ops_turn_n3: band(r => r.opsN3),
      quality_no_behavioural: band(r => r.cleanNoBehav),
      quality_full: band(r => r.clean),
    },
  };
  // reveal / scarf on the OPS def and on the full quality def
  function reveal(sel) {
    let n = 0, mv = 0, nm = 0, it = 0, ab = 0;
    for (const r of G.filter(sel)) for (const e of r.sets) { n++; mv += e.mv; ab += e.ab; if (!e.mega) { nm++; it += e.item; } }
    return { entries: n, moves_mean: +(mv / n).toFixed(3), moves_share: +(mv / n / 4).toFixed(4),
             item_share_nonmega: +(it / nm).toFixed(4), nonmega_entries: nm, ability_share: +(ab / n).toFixed(4) };
  }
  function scarf(sel) {
    let t = 0, s = 0, t13 = 0, s13 = 0, g13t = 0, g13s = 0;
    for (const r of G.filter(sel)) for (const sd of ['p1', 'p2']) {
      t++; s += r.scarf[sd];
      if ((+r[sd].rating || 0) >= 1300) { t13++; s13 += r.scarf[sd]; }
      if (lo(r) >= 1300) { g13t++; g13s += r.scarf[sd]; }
    }
    return { teams: t, scarf: s, share: +(s / t).toFixed(4), teams_own_1300: t13, share_own_1300: +(s13 / t13).toFixed(4),
             teams_in_lower1300_games: g13t, share_lower1300_games: +(g13s / g13t).toFixed(4) };
  }
  if (kind === 'bo1') out.reveal = { ops: reveal(r => r.opsLen), quality_full: reveal(r => r.clean) };
  else out.scarf = { ops: scarf(r => r.opsLen), quality_full: scarf(r => r.clean) };

  // ladder overlap
  const L = JSON.parse(fs.readFileSync(ladderFile, 'utf8')).toplist;
  const cnt = new Map(), cntClean = new Map();
  for (const r of G) for (const sd of ['p1', 'p2']) {
    const u = uid(r[sd].name); cnt.set(u, (cnt.get(u) || 0) + 1);
    if (r.clean) cntClean.set(u, (cntClean.get(u) || 0) + 1);
  }
  const ladder = {};
  const bands = [['top100', p => true, 100], ['elo>=1500', p => p.elo >= 1500], ['elo>=1600', p => p.elo >= 1600], ['elo>=1700', p => p.elo >= 1700], ['all_listed', p => true]];
  for (const [name, f, topN] of bands) {
    let P = L.filter(f); if (topN) P = L.slice(0, topN);
    const inStore = P.filter(p => cnt.get(p.userid));
    const ladderGames = P.reduce((a, p) => a + (p.w + p.l + p.t), 0);
    const held = P.reduce((a, p) => a + (cnt.get(p.userid) || 0), 0);
    const heldClean = P.reduce((a, p) => a + (cntClean.get(p.userid) || 0), 0);
    ladder[name] = { players: P.length, in_store: inStore.length, zero_uploads: P.length - inStore.length,
      zero_share: +((P.length - inStore.length) / P.length).toFixed(4),
      player_games_held: held, player_games_held_clean: heldClean, ladder_wlt_sum: ladderGames,
      held_share_of_wlt: +(held / ladderGames).toFixed(4) };
  }
  // most recent game in the store per top ladder player, vs their last_played
  out.ladder = { file: ladderFile, top_elo: L[0] && Math.max(...L.map(p => p.elo)), listed: L.length, bands: ladder };

  // bo3 series
  if (kind === 'bo3') {
    const byPair = new Map();
    for (const r of G) {
      const k = [uid(r.p1.name), uid(r.p2.name)].sort().join('|');
      if (!byPair.has(k)) byPair.set(k, []);
      byPair.get(k).push(r);
    }
    const ts = d => Date.parse(d.replace(' ', 'T') + ':00Z');
    function series(gapMin) {
      const S = [];
      for (const [k, arr] of byPair) {
        arr.sort((a, b) => a.num - b.num);
        let cur = null;
        for (const r of arr) {
          const done = cur && (cur.games.length >= 3 || Object.values(cur.wins).some(w => w >= 2));
          if (!cur || done || ts(r.date) - ts(cur.last) > gapMin * 60000) { cur = { games: [], wins: {}, last: r.date }; S.push(cur); }
          cur.games.push(r); cur.last = r.date;
          const w = uid(r.winner); if (w) cur.wins[w] = (cur.wins[w] || 0) + 1;
        }
      }
      const len = { 1: 0, 2: 0, 3: 0 };
      let decided = 0, anyClean = 0, allClean = 0, lo1500 = 0, lo1300 = 0;
      for (const s of S) {
        len[s.games.length]++;
        if (Object.values(s.wins).some(w => w >= 2)) decided++;
        if (s.games.some(g => g.clean)) anyClean++;
        if (s.games.every(g => g.clean)) allClean++;
        const l = Math.max(...s.games.map(lo)); if (l >= 1300) lo1300++; if (l >= 1500) lo1500++;
      }
      return { gap_min: gapMin, series: S.length, by_length: len, decided_2_wins: decided,
               with_any_clean_game: anyClean, all_games_clean: allClean, lower_ge_1300: lo1300, lower_ge_1500: lo1500 };
    }
    out.series = [15, 30, 60].map(series);
    out.series_pairs = byPair.size;
  }
  fs.writeFileSync(outFile, JSON.stringify(out, null, 1));
  console.log(JSON.stringify(out, (k, v) => k === 'behavioural_bots' ? v.length : v, 1));
})();
